def transform(grid):
    out=[row[:] for row in grid]
    coords=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v!=max(set(x for rr in grid for x in rr),key=lambda x:sum(rr.count(x) for rr in grid))]
    if not coords:return out
    r0=min(r for r,c in coords); r1=max(r for r,c in coords); c0=min(c for r,c in coords); c1=max(c for r,c in coords)
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if (r in (r0,r1) or c in (c0,c1)) and grid[r][c]==max(set(x for rr in grid for x in rr),key=lambda x:sum(rr.count(x) for rr in grid)):
                out[r][c]=2
    return out
